module benchmark/solution

import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/list (foldl)
import std/option (getOrElse)

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let contents = readFile(filename);
      let total = foldl(func(acc: int, line: string) -> int {
        acc + getOrElse(stringToInt(trim(line)), 0)
      }, 0, split(contents, "\n"));
      println(show(total))
    },
    [] => ()
  }
}

